387	    /**
388	     * Returns the trimmed {@code Idempotency-Key} header of the current request, or {@code null} when
389	     * the header is absent, blank or there is no active request. A present key opts a create into the
390	     * idempotent-repeat behaviour tracked by {@link #idempotentCreates}.
391	     */
392	    private String idempotencyKey() {
393	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
394	            return null;
395	        }
396	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
