403	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
404	        List<String> missingFields = new ArrayList<>();
405	        if (isBlank(ownerFieldsDto.getFirstName())) {
406	            missingFields.add("firstName");
407	        }
408	        if (isBlank(ownerFieldsDto.getLastName())) {
409	            missingFields.add("lastName");
410	        }
