428	
429	    /**
430	     * Normalizes an owner's address on create, supporting both the structured form
431	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
432	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
433	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
434	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
435	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
436	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
437	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
438	     * flat {@code address} when no structured line is given - is written onto the request so it is what
439	     * gets validated, compared, stored and returned. Running before the required-field check means an
440	     * address that is blank in both forms after normalization is rejected like a missing one.
441	     */
442	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
443	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
444	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
445	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
446	        ownerFieldsDto.setAddressLine1(line1);
447	        ownerFieldsDto.setAddressLine2(line2);
448	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
449	    }
450	
451	    /**
452	     * Composes the effective address, preferring the structured form: when {@code line1} is present
453	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
454	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
455	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
456	     * left for the required-field check to reject) when no structured line is supplied.
457	     */
458	    private static String composeAddress(String line1, String line2, String flat) {
459	        if (line1 != null && !line1.isBlank()) {
460	            if (line2 != null && !line2.isBlank()) {
461	                return line1 + " " + line2;
462	            }
463	            return line1;
464	        }
