468	    /**
469	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
470	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
471	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
472	     * address is returned unchanged, making it safe to apply to stored values during comparison.
473	     */
474	    private static String canonicalAddress(String address) {
475	        if (address == null) {
476	            return null;
477	        }
478	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
479	        if (collapsed.isEmpty()) {
480	            return "";
481	        }
482	        String[] tokens = collapsed.split(" ");
483	        StringBuilder sb = new StringBuilder(collapsed.length());
484	        for (int i = 0; i < tokens.length; i++) {
485	            if (i > 0) {
486	                sb.append(' ');
487	            }
488	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
489	        }
490	        return sb.toString();
491	    }
