493	    /**
494	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
495	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
496	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
497	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
498	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
499	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
500	     * written back onto the request so it is what gets stored and returned. Any value that cannot
501	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
502	     * {@code telephone}.
503	     */
504	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
505	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
506	    }
