508	    /**
509	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
510	     * (400) naming {@code telephone} when it cannot form a valid number.
511	     */
512	    private static String toE164(String telephone) {
513	        if (telephone == null) {
514	            throw new InvalidOwnerFieldsException(List.of("telephone"));
515	        }
516	        boolean hasCountryCode = telephone.trim().startsWith("+");
517	        String digits = telephone.replaceAll("\\D", "");
518	        String countryCode;
519	        String national;
520	        if (hasCountryCode) {
521	            countryCode = matchCountryCode(digits);
522	            national = digits;
523	        } else {
524	            countryCode = "61";
525	            if (digits.startsWith("0")) {
526	                digits = digits.substring(1);
527	            }
528	            national = "61" + digits;
529	        }
530	        if (!national.matches("[0-9]{8,15}")) {
531	            throw new InvalidOwnerFieldsException(List.of("telephone"));
532	        }
533	        if (countryCode != null) {
534	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
535	            if (requiredLength != null
536	                && national.length() - countryCode.length() != requiredLength) {
537	                throw new InvalidOwnerFieldsException(List.of("telephone"));
538	            }
539	        }
540	        return "+" + national;
541	    }
