543	    /**
544	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
545	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
546	     * the number is not length-checked against a country.
547	     */
548	    private static String matchCountryCode(String digits) {
549	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
550	            .filter(digits::startsWith)
551	            .max(Comparator.comparingInt(String::length))
552	            .orElse(null);
553	    }
