555	    /**
556	     * Rejects creating an owner that duplicates an existing one on the derived {@code identityKey} -
557	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
558	     * soundex(lastName)} (see {@link IdentityKey}). An exact key match means the same telephone, email
559	     * and same-sounding surname, i.e. the same person re-registering; because the telephone is part of
560	     * the key, two people who merely share a surname (and postcode) but carry different telephones no
561	     * longer collide here - they are surfaced as a soft match instead (see
562	     * {@link #assignPossibleDuplicate}). This single identity key is the only hard-duplicate rule; the
563	     * computed {@code householdId} no longer contributes a separate 409. A match is a 409.
564	     *
565	     * <p>Owners flagged {@code deleted} (soft-deleted via {@code DELETE /api/owners/{id}}) are skipped
566	     * entirely, so a normally-blocking duplicate is allowed when the only matching owner has been
567	     * deleted.
568	     *
569	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block. The incoming telephone
570	     * and email have already been normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}
571	     * (the email-domain blocklist applies first, in {@link #normalizeEmail}); each existing owner's key
572	     * is derived the same way before comparison. A match results in a 409 response naming
573	     * {@code identityKey}.
574	     */
575	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto) {
576	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
577	            return;
578	        }
579	        String identityKey = IdentityKey.of(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(),
580	            ownerFieldsDto.getLastName());
581	        for (Owner existing : this.clinicService.findAllOwners()) {
582	            if (Boolean.TRUE.equals(existing.getDeleted())) {
583	                continue;
584	            }
585	            if (identityKey.equals(existingIdentityKey(existing))) {
586	                throw new DuplicateOwnerIdentityException(identityKey);
587	            }
588	        }
589	    }
