716	    /**
717	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
718	     * day. When the caller supplies no value it defaults to the server's current date; a value
719	     * provided in the request is kept. A supplied value later than the server's current date is
720	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
721	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
722	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
723	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
724	     * every value derived from the registration date is based on.
725	     */
726	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
727	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
728	        if (effective == null) {
729	            effective = LocalDate.now();
730	        }
731	        else if (effective.isAfter(LocalDate.now())) {
732	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
