737	    /**
738	     * The fixed public-holiday calendar. A registration date landing on one of these days is rolled
739	     * forward, just like a weekend, until it reaches a non-holiday business day.
740	     */
741	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
742	        LocalDate.of(2026, 1, 1),
743	        LocalDate.of(2026, 1, 26),
744	        LocalDate.of(2026, 4, 25),
745	        LocalDate.of(2026, 12, 25),
746	        LocalDate.of(2026, 12, 28));
