748	    /**
749	     * Rolls a date forward onto a business day: a Saturday, Sunday or listed public holiday is
750	     * advanced one day at a time until it reaches the next non-holiday business day; a weekday that
751	     * is not a holiday is returned unchanged.
752	     */
753	    private static LocalDate toBusinessDay(LocalDate date) {
754	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
755	            date = date.plusDays(1);
756	        }
757	        return date;
758	    }
