760	    /**
761	     * Returns whether the given date falls on a Saturday or Sunday.
762	     */
763	    private static boolean isWeekend(LocalDate date) {
764	        return switch (date.getDayOfWeek()) {
765	            case SATURDAY, SUNDAY -> true;
766	            default -> false;
767	        };
768	    }
