785	    /**
786	     * Returns {@code customerCode} unchanged when no existing owner already carries it; otherwise
787	     * appends {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by
788	     * any existing owner. Compared against the pre-existing owners, so the returned code is unique
789	     * among them.
790	     */
791	    private String deduplicateCustomerCode(String customerCode) {
792	        Set<String> existing = new HashSet<>();
793	        for (Owner owner : this.clinicService.findAllOwners()) {
794	            if (owner.getCustomerCode() != null) {
795	                existing.add(owner.getCustomerCode());
796	            }
797	        }
798	        if (!existing.contains(customerCode)) {
799	            return customerCode;
800	        }
801	        int n = 2;
802	        while (existing.contains(customerCode + "-" + n)) {
803	            n++;
804	        }
805	        return customerCode + "-" + n;
806	    }
