840	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
841	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
842	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
843	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
844	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
845	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
846	     * tenure, so the tenure bonus never applies on create.
847	     */
848	    private void assignMembership(Owner owner) {
849	        int points = 0;
850	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
851	            points += 2;
852	        }
853	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
854	            points += 1;
855	        }
856	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
857	            points += 2;
858	        }
859	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
860	            points += 3;
861	        }
862	        owner.setMembershipPoints(points);
863	        owner.setMembershipLevel(capMembershipLevelByHousehold(owner, membershipLevelForPoints(points)));
