866	    /**
867	     * Caps a newly derived {@code membershipLevel} so it cannot exceed one above the current maximum
868	     * {@code membershipLevel} among the new owner's existing household members - the pre-existing owners
869	     * already carrying the same {@code householdId}. When the owner belongs to no household, or has no
870	     * existing household member, no cap applies and the derived level is returned unchanged. Runs after
871	     * {@link #assignHouseholdMembership} so the owner's {@code householdId} is settled.
872	     */
873	    private int capMembershipLevelByHousehold(Owner owner, int derivedLevel) {
874	        String householdId = owner.getHouseholdId();
875	        if (householdId == null || householdId.isBlank()) {
876	            return derivedLevel;
877	        }
878	        Integer maxHouseholdLevel = null;
879	        for (Owner existing : this.clinicService.findAllOwners()) {
880	            if (householdId.equals(existing.getHouseholdId()) && existing.getMembershipLevel() != null
881	                && (maxHouseholdLevel == null || existing.getMembershipLevel() > maxHouseholdLevel)) {
882	                maxHouseholdLevel = existing.getMembershipLevel();
883	            }
884	        }
885	        if (maxHouseholdLevel == null) {
886	            return derivedLevel;
887	        }
888	        return Math.min(derivedLevel, maxHouseholdLevel + 1);
889	    }
