895	    private int membershipLevelForPoints(int points) {
896	        if (points <= 1) {
897	            return 1;
898	        }
899	        if (points <= 3) {
900	            return 2;
901	        }
902	        if (points <= 5) {
903	            return 3;
904	        }
905	        return 4;
906	    }
