952	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
953	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
954	            owner.setPossibleDuplicate(false);
955	            owner.setPossibleDuplicateOf(null);
956	            return;
957	        }
958	        String postcode = owner.getPostcode();
959	        String soundex = IdentityKey.soundex(owner.getLastName());
960	        String identityKey = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
961	        Integer matchId = null;
962	        if (postcode != null && !postcode.isBlank()) {
963	            for (Owner existing : this.clinicService.findAllOwners()) {
964	                if (soundex.equals(IdentityKey.soundex(existing.getLastName()))
965	                    && postcode.equals(existing.getPostcode())
966	                    && !identityKey.equals(existingIdentityKey(existing))
967	                    && existing.getId() != null
968	                    && (matchId == null || existing.getId() < matchId)) {
969	                    matchId = existing.getId();
970	                }
971	            }
972	        }
973	        owner.setPossibleDuplicate(matchId != null);
974	        owner.setPossibleDuplicateOf(matchId);
975	    }
