979	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
980	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
981	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
982	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
983	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
984	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
985	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
986	     * ({@link #assignHouseholdMembership}).
987	     */
988	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
989	        String postcode = ownerFieldsDto.getPostcode();
990	        if (postcode == null || postcode.isBlank()) {
991	            return null;
992	        }
993	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
994	        return shaHexUpper(lastName + "|" + postcode, 12);
995	    }
996	
997	    /**
998	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
999	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
1000	     * every existing owner already carrying the same identifier. Runs after the owner's
1001	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
1002	     * Left {@code null} when the owner belongs to no household.
1003	     */
1004	    private void assignHouseholdMembership(Owner owner) {
1005	        String householdId = owner.getHouseholdId();
1006	        if (householdId == null || householdId.isBlank()) {
1007	            owner.setHouseholdMemberCount(null);
1008	            return;
1009	        }
1010	        int count = 1;
1011	        for (Owner existing : this.clinicService.findAllOwners()) {
1012	            if (householdId.equals(existing.getHouseholdId())) {
1013	                count++;
1014	            }
1015	        }
1016	        owner.setHouseholdMemberCount(count);
1017	    }
1018	
1019	    /**
1020	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
1021	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
1022	     * identifier, both stable functions of their inputs.
1023	     */
1024	    private static String shaHexUpper(String input, int length) {
1025	        try {
1026	            byte[] digest = MessageDigest.getInstance("SHA-256")
1027	                .digest(input.getBytes(StandardCharsets.UTF_8));
1028	            StringBuilder hex = new StringBuilder(digest.length * 2);
1029	            for (byte b : digest) {
1030	                hex.append(String.format("%02x", b));
1031	            }
1032	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
1033	        } catch (NoSuchAlgorithmException ex) {
1034	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
1035	        }
1036	    }
1037	}
